import type { IconName } from "@/components/ui/icons";

/**
 * DEMO LESSON CONTENT for three chapters. Every other chapter shows "coming soon".
 * Later this is generated by AI from the chapter text and approved by the teacher.
 * NOTE: the Maths chapter 1 content is generic place-value practice, written only so a new child
 * has something to try. Replace it with questions written from the real chapter.
 */
export type Option = { id: string; text: string };
export type Question = {
  id: string;
  prompt: string;
  options: Option[];
  correctId: string;
  hint: string;
};
export type Idea = {
  id: string;
  chapterId: string;
  title: string;
  minutes: number;
  story: { icon: IconName; caption: string }[]; // "photo story" panels
  picture: { big: string; caption: string }; // the picture / diagram way
  real: { icon: IconName; line1: string; line2: string }; // real-life way
  questions: Question[];
};

const q = (
  id: string,
  prompt: string,
  options: [string, string, string],
  correct: 0 | 1 | 2,
  hint: string,
): Question => ({
  id,
  prompt,
  options: options.map((text, i) => ({ id: `${id}-o${i}`, text })),
  correctId: `${id}-o${correct}`,
  hint,
});

